/* The catalogue is generated by scripts/import-nalya.py from the legacy client. */
(() => {
  'use strict';
  const byId = id => document.getElementById(id);
  const controls = {
    search: byId('db-search'), section: byId('section-filter'), location: byId('location-filter'),
    event: byId('event-filter'), level: byId('level-filter'), currency: byId('currency-filter'),
    sc: byId('sc-filter'), js: byId('js-filter'), sort: byId('sort-filter'),
    hairType: byId('hair-type-filter'), hairColour: byId('hair-colour-filter')
  };
  const grid = byId('item-grid');
  const dialog = byId('catalogue-dialog');
  const pageSize = 36;
  let entries = [];
  let category = '';
  let visible = pageSize;
  let loaded = false;
  let variantGroups = {};
  let entryIndex = new Map();
  let renderTimer;
  const wishlist = window.BadRosesWishlist.createStore();
  let wishlistOnly = false;
  const number = value => Number(value).toLocaleString();
  const el = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  };
  const knownNumber = value => typeof value === 'number' && Number.isFinite(value);
  const baseEntries = () => wishlistOnly ? entries.filter(item => wishlist.has(item.id)) : entries;
  const currentValue = input => input.value.trim() === '' ? null : Number(input.value);
  const variantLabel = item => item.variant && !/^Coat\s+\d+$/i.test(item.variant)
    ? item.variant : item.kind === 'horse' ? 'Coat variant' : 'Colour variant';
  const eventLabel = item => item.events.length ? item.events.join(', ') : 'Unknown';
  const wishlistName = item => item.title + (item.kind === 'horse' || item.section === 'Hairstyles' ? ' · ' + variantLabel(item) : '');
  const portraitAtLocation = item => {
    const view = item.section === 'Hairstyles' && item.imageViews?.find(view => view.location === controls.location.value);
    return view ? {...item, ...view} : item;
  };

  function updateWishlistButton(button, item) {
    const saved = wishlist.has(item.id);
    button.textContent = saved ? '♥' : '♡';
    button.setAttribute('aria-pressed', String(saved));
    button.setAttribute('aria-label', (saved ? 'Remove ' : 'Save ') + wishlistName(item) + (saved ? ' from wishlist' : ' to wishlist'));
    button.title = saved ? 'Remove from wishlist' : 'Save to wishlist';
    if (button.classList.contains('catalogue-wishlist-detail')) button.append(el('span', '', saved ? 'Saved to wishlist' : 'Save to wishlist'));
  }

  function refreshWishlistButtons() {
    document.querySelectorAll('[data-wishlist-id]').forEach(button => {
      const item = entryIndex.get(button.dataset.wishlistId);
      if (item) updateWishlistButton(button, item);
    });
  }

  function refreshWishlistFilters() {
    if (!wishlistOnly) return;
    if (category && !baseEntries().some(item => item.category === category)) category = '';
    categoryButtons();
    sections();
  }

  function wishlistButton(item, detail = false) {
    const button = el('button', 'catalogue-wishlist-save' + (detail ? ' catalogue-wishlist-detail' : ''));
    button.type = 'button';
    button.dataset.wishlistId = item.id;
    updateWishlistButton(button, item);
    button.addEventListener('click', () => {
      const saved = wishlist.toggle(item.id);
      refreshWishlistFilters();
      renderDatabase();
      refreshWishlistButtons();
      byId('catalogue-wishlist-status').textContent = wishlistName(item) + (saved ? ' added to your wishlist.' : ' removed from your wishlist.') + (wishlist.persistent ? '' : ' Browser storage is unavailable; changes are saved for this page visit only.');
      if (button.isConnected) button.focus({preventScroll:true});
      else (grid.querySelector('[data-wishlist-id="' + item.id + '"]') || byId('catalogue-wishlist-tab')).focus({preventScroll:true});
    });
    return button;
  }

  function framedImage(item, image) {
    const f = item.imageFrame;
    if (!f) return image;
    const frame = el('span', 'catalogue-portrait-frame');
    frame.style.aspectRatio = f.width + ' / ' + f.height;
    image.style.width = (100 * f.sourceWidth / f.width) + '%';
    image.style.height = (100 * f.sourceHeight / f.height) + '%';
    image.style.left = (-100 * f.x / f.width) + '%';
    image.style.top = (-100 * f.y / f.height) + '%';
    image.style.padding = '0';
    frame.append(image);
    return frame;
  }

  function picture(item, large = false) {
    const figure = el('figure', 'catalogue-picture' + (large ? ' catalogue-picture-large' : '') + (item.image?.includes('/photos/') ? ' catalogue-photo' : '') + (item.section === 'Hairstyles' ? ' catalogue-hair' : ''));
    const unavailable = () => {
      figure.replaceChildren(el('span', 'catalogue-no-image', 'Preview unavailable'));
    };
    if (!item.image) {
      unavailable();
      return figure;
    }
    const image = el('img');
    image.alt = item.kind === 'horse' ? item.breed + ' — ' + item.imageKind : item.section === 'Hairstyles' ? item.title + ' — ' + item.variant : item.title;
    image.loading = large ? 'eager' : 'lazy';
    image.decoding = 'async';
    image.referrerPolicy = 'no-referrer';
    image.width = large ? 320 : 160;
    image.height = large ? 280 : 144;
    image.src = item.image;
    image.addEventListener('error', () => {
      if (item.fallbackImage && image.getAttribute('src') !== item.fallbackImage) {
        image.removeAttribute('style');
        image.closest('.catalogue-portrait-frame')?.replaceWith(image);
        image.src = item.fallbackImage;
        caption.textContent = item.kind === 'horse' ? 'Horse icon · coat preview unavailable' : 'Game icon';
      } else unavailable();
    });
    const caption = el('figcaption', '', item.imageKind);
    figure.append(framedImage(item, image), caption);
    return figure;
  }

  function prices(item) {
    const wrapper = el('div', 'catalogue-prices');
    if (knownNumber(item.priceSC) && item.priceSC > 0) {
      wrapper.append(el('span', 'price-sc', number(item.priceSC) + ' SC'));
    }
    if (knownNumber(item.priceJS) && item.priceJS > 0) {
      if (wrapper.childNodes.length) wrapper.append(el('span', 'price-or', 'or'));
      wrapper.append(el('span', 'price-js', number(item.priceJS) + ' JS'));
    }
    for (const cost of item.currencies || []) wrapper.append(el('span', 'price-token', number(cost.count) + ' ' + cost.name));
    if (!wrapper.childNodes.length) wrapper.append(el('span', 'price-unlisted', 'No price listed'));
    return wrapper;
  }

  function categoryButtons() {
    const available = baseEntries();
    const categories = ['', ...new Set(available.map(item => item.category))];
    const priority = ['Clothes', 'Equipment', 'Horses & Pets', 'Horse Decorations', 'Player Accessories', 'Beauty'];
    categories.sort((a, b) => {
      const rank = value => value === '' ? -1 : priority.includes(value) ? priority.indexOf(value) : 99;
      return rank(a) - rank(b) || a.localeCompare(b);
    });
    byId('category-list').replaceChildren(...categories.map(value => {
      const count = available.filter(item => !value || item.category === value).length;
      const button = el('button', 'category-button' + (category === value ? ' selected' : ''));
      button.type = 'button';
      button.disabled = count === 0;
      button.setAttribute('aria-pressed', String(category === value));
      button.append(el('span', '', value || 'All collections'), el('span', '', number(count)));
      button.addEventListener('click', () => {
        category = value;
        visible = pageSize;
        controls.section.value = '';
        categoryButtons();
        sections();
        renderDatabase();
      });
      return button;
    }));
  }

  function setOptions(select, values, label) {
    const previous = select.value;
    select.replaceChildren(new Option(label, ''), ...values.map(value => new Option(value, value)));
    if (values.includes(previous)) select.value = previous;
  }

  function sections() {
    setOptions(controls.section, [...new Set(baseEntries().filter(item => !category || item.category === category)
      .map(item => item.section))].sort(), 'All types');
  }

  function matchesFilters(item) {
    if (category && item.category !== category) return false;
    if (controls.section.value && item.section !== controls.section.value) return false;
    if (controls.section.value === 'Hairstyles') {
      if (controls.hairType.value && item.hairType !== controls.hairType.value) return false;
      if (controls.hairColour.value && item.hairColour !== controls.hairColour.value) return false;
    }
    if (controls.location.value && !item.locations.includes(controls.location.value)) return false;
    const event = controls.event.value;
    if (event === 'event' && !item.events.length) return false;
    if (event === 'untagged' && item.events.length) return false;
    if (event && !['event', 'untagged'].includes(event) && !item.events.includes(event)) return false;
    const level = currentValue(controls.level);
    if (level !== null && (!knownNumber(item.requiredLevel) || item.requiredLevel > level)) return false;
    const sc = currentValue(controls.sc);
    if (sc !== null && (!knownNumber(item.priceSC) || item.priceSC <= 0 || item.priceSC > sc)) return false;
    const js = currentValue(controls.js);
    if (js !== null && (!knownNumber(item.priceJS) || item.priceJS <= 0 || item.priceJS > js)) return false;
    const currency = controls.currency.value;
    if (currency === 'SC' && !(item.priceSC > 0)) return false;
    if (currency === 'JS' && !(item.priceJS > 0)) return false;
    if (currency === 'tokens' && !item.currencies.length) return false;
    if (currency === 'none' && (item.priceSC > 0 || item.priceJS > 0 || item.currencies.length)) return false;
    const terms = controls.search.value.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);
    return terms.every(term => item.searchText.includes(term));
  }

  function card(item) {
    item = portraitAtLocation(item);
    const article = el('article', 'catalogue-card');
    const imageButton = el('button', 'catalogue-image-button');
    imageButton.type = 'button';
    imageButton.setAttribute('aria-label', 'View ' + item.title);
    imageButton.append(picture(item));
    const variantCount = variantGroups[item.variantGroup]?.length || item.previewVariantCount;
    if (variantCount > 1) imageButton.append(el('span', 'catalogue-variant-count', variantCount + (item.kind === 'horse' ? ' coats' : ' colours')));
    imageButton.addEventListener('click', () => openEntry(item));
    article.append(imageButton);
    article.append(wishlistButton(item));
    const body = el('div', 'catalogue-card-body');
    const top = el('div', 'catalogue-card-top');
    top.append(el('span', '', item.section), el('span', '', item.photoGeneration || ''));
    const name = el('h3');
    const nameButton = el('button', 'catalogue-name', item.title);
    nameButton.type = 'button';
    nameButton.addEventListener('click', () => openEntry(item));
    name.append(nameButton);
    body.append(top, name);
    if (item.section === 'Hairstyles' || wishlistOnly && item.kind === 'horse') body.append(el('p', 'catalogue-variant', variantLabel(item)));
    const badges = el('div', 'catalogue-badges');
    if (item.events.length) badges.append(el('span', 'catalogue-event', item.events.join(' · ')));
    else if (item.locations.length) item.locations.forEach(location => {
      const badge = el('span', 'catalogue-place', location);
      badge.setAttribute('aria-label', 'Location: ' + location);
      badges.append(badge);
    });
    else badges.append(el('span', 'catalogue-place', 'Location: Unknown'));
    if (badges.childNodes.length) body.append(badges);
    if (item.events.length && item.locations.length) body.append(el('p', 'catalogue-location', item.locations.slice(0,2).join(' · ')));
    const bottom = el('div', 'catalogue-card-bottom');
    bottom.append(prices(item));
    if (item.requiredLevel > 0) bottom.append(el('span', 'catalogue-level', 'Lvl ' + item.requiredLevel));
    body.append(bottom);
    article.append(body);
    return article;
  }

  function renderDatabase() {
    if (!loaded) return;
    byId('catalogue-hair-filters').hidden = controls.section.value !== 'Hairstyles';
    const filtered = baseEntries().filter(matchesFilters);
    const unknownLast = (a, b, key) => {
      const value = item => knownNumber(item[key]) && (key === 'requiredLevel' || item[key] > 0) ? item[key] : Infinity;
      return value(a) - value(b) || a.title.localeCompare(b.title) || a.id.localeCompare(b.id);
    };
    const sort = controls.sort.value;
    const featureRank = item => item.kind === 'horse' ? 0 : item.section === 'Hairstyles' ? 1 : item.section === 'Makeup' ? 2 : item.category === 'Clothes' ? 3 : item.category === 'Quest Items' ? 9 : 4;
    filtered.sort(sort === 'za' ? (a, b) => b.title.localeCompare(a.title) :
      sort === 'featured' ? (a,b) => featureRank(a)-featureRank(b) || a.title.localeCompare(b.title) || Number(String(a.internalName).includes('_Free')) - Number(String(b.internalName).includes('_Free')) || a.id.localeCompare(b.id) :
      ['priceSC', 'priceJS', 'requiredLevel'].includes(sort) ? (a, b) => unknownLast(a, b, sort) :
      (a, b) => a.title.localeCompare(b.title) || a.id.localeCompare(b.id));
    const previews = [];
    const grouped = new Map();
    for (const item of filtered) {
      const key = wishlistOnly ? item.id : item.section === 'Hairstyles' ? item.hairStyle + ':' + item.hairMaterial : item.variantGroup || item.id;
      if (grouped.has(key)) grouped.get(key).previewVariantCount++;
      else {
        const preview = {...item,previewVariantCount:1};
        grouped.set(key,preview);
        previews.push(preview);
      }
    }
    grid.replaceChildren(...previews.slice(0, visible).map(card));
    byId('result-count').textContent = number(filtered.length) + (filtered.length === 1 ? ' entry' : ' entries');
    byId('result-context').textContent = (wishlistOnly ? 'My wishlist' + (category ? ' · ' + category : '') : category || 'All collections') + (controls.section.value === 'Hairstyles' && !wishlistOnly ? ' · each hair colour shown separately' : previews.length < filtered.length ? ' · colour & coat variants grouped' : '');
    byId('empty-state').hidden = filtered.length !== 0;
    const emptyWishlist = wishlistOnly && !entries.some(item => wishlist.has(item.id));
    byId('empty-state').querySelector('h3').textContent = emptyWishlist ? 'Your wishlist is waiting.' : 'Nothing here just yet.';
    byId('empty-state').querySelector('p').textContent = emptyWishlist ? 'Save a little favourite with the heart on an item or horse. Pick a coat or colour in its details to save that exact variant.' : 'Try a different name or give your filters a little more room.';
    byId('empty-clear-filters').textContent = emptyWishlist ? 'Explore the catalogue' : 'Clear filters';
    byId('catalogue-wishlist-count').textContent = number(entries.filter(item => wishlist.has(item.id)).length);
    const wishlistNote = byId('catalogue-wishlist-note');
    wishlistNote.hidden = !wishlistOnly && wishlist.persistent;
    wishlistNote.textContent = wishlist.persistent ? 'Saved in this browser, with no account needed. Your chosen coats and colours are saved separately. Clearing browser data removes your wishlist; it does not sync to other devices.' : 'Browser storage is unavailable. Your wishlist will last for this page visit only and will disappear when you leave or reload.';
    byId('load-more').hidden = visible >= previews.length;
    byId('load-more').textContent = 'Show ' + Math.min(pageSize, previews.length - visible) + ' more';
    byId('catalogue-showing').textContent = filtered.length ? 'Showing ' + number(Math.min(visible, previews.length)) + ' of ' + number(previews.length) + ' previews' : '';
    const focus = wishlistOnly ? 'wishlist' : category==='Horses & Pets' && controls.section.value==='Horses' ? 'horses' : category==='Beauty' && controls.section.value==='Hairstyles' ? 'hair' : category==='Beauty' && controls.section.value==='Makeup' ? 'makeup' : !category && !controls.section.value ? 'all' : '';
    document.querySelectorAll('[data-catalogue-focus]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.catalogueFocus===focus)));
  }
  window.renderDatabase = renderDatabase;

  function fact(list, label, value) {
    const group = el('div');
    group.append(el('dt', '', label), el('dd', '', value));
    list.append(group);
  }

  function openEntry(item) {
    item = portraitAtLocation(item);
    const body = byId('catalogue-dialog-content');
    const visual = el('div', 'catalogue-dialog-visual');
    visual.append(picture(item, true));
    if (item.imageViews?.length > 1) {
      const views = el('div', 'catalogue-image-views');
      for (const view of item.imageViews) {
        const button = el('button', '', view.label);
        button.type = 'button';
        button.setAttribute('aria-pressed', String(view.image === item.image));
        button.addEventListener('click', () => {
          visual.querySelector('figure').replaceWith(picture({...item,...view,imageKind:view.imageKind || view.label},true));
          views.querySelectorAll('button').forEach(b => b.setAttribute('aria-pressed',String(b === button)));
        });
        views.append(button);
      }
      visual.append(views);
    }
    const group = (variantGroups[item.variantGroup] || []).map(id => entryIndex.get(id)).filter(Boolean);
    if (group.length > 1) {
      visual.append(el('h3', 'catalogue-variants-heading', item.kind === 'horse' ? 'Coats in your game' : 'Colours in your game'));
      const choices = el('div', 'catalogue-variant-choices');
      for (const [index, variant] of group.entries()) {
        const label = variantLabel(variant);
        const button = el('button', 'catalogue-variant-choice');
        button.type = 'button';
        button.title = label;
        button.setAttribute('aria-label','View ' + label.toLowerCase() + ', option ' + (index + 1));
        button.setAttribute('aria-pressed',String(variant.id === item.id));
        const thumb = el('img');
        const preview = portraitAtLocation(variant);
        thumb.src = preview.image || preview.fallbackImage;
        thumb.alt = '';
        thumb.loading = 'lazy';
        const thumbFrame = el('span', 'catalogue-variant-thumb');
        thumbFrame.append(framedImage(preview, thumb));
        button.append(thumbFrame,el('span','',label));
        button.addEventListener('click',()=>openEntry(variant));
        choices.append(button);
      }
      visual.append(choices);
    }
    const content = el('div', 'catalogue-dialog-copy');
    content.append(el('p', 'eyebrow', item.category + ' / ' + item.section));
    const heading = el('h2', '', item.title);
    heading.id = 'catalogue-dialog-title';
    content.append(heading);
    content.append(wishlistButton(item, true));
    if (item.kind === 'horse') content.append(el('p', 'catalogue-variant', item.breed + ' · ' + variantLabel(item)));
    if (item.section === 'Hairstyles') content.append(el('p', 'catalogue-variant', item.hairColour + ' · ' + item.hairLength.toLowerCase() + ' hair'));
    if (item.description) content.append(el('p', 'catalogue-description', item.description));
    content.append(prices(item));
    const facts = el('dl', 'catalogue-facts');
    if (item.section === 'Hairstyles') {
      fact(facts, 'Hair type', item.hairType);
      fact(facts, 'Colour', item.hairColour);
      fact(facts, 'Length', item.hairLength);
    }
    fact(facts, 'Required level', knownNumber(item.requiredLevel) ? item.requiredLevel === 0 ? 'No level requirement' : 'Level ' + item.requiredLevel : 'Not listed');
    fact(facts, 'Star Coins', item.priceSC > 0 ? number(item.priceSC) + ' SC' : 'No price listed');
    fact(facts, 'Jorvik Shillings', item.priceJS > 0 ? number(item.priceJS) + ' JS' : 'No price listed');
    fact(facts, 'Event', eventLabel(item));
    if (item.season) fact(facts, 'Season', item.season);
    fact(facts, item.kind === 'horse' ? 'Sale location' : 'Shop location / region', item.locations.length ? item.locations.join(', ') : 'Not listed in client');
    if (item.locationSource) fact(facts, 'Location detail', item.locationSource);
    fact(facts, 'Reputation', item.reputation ? item.reputation.faction + (item.reputation.level ? ' · tier ' + item.reputation.level : ' · no tier requirement') : 'No faction requirement listed');
    if (item.currencies.length) fact(facts, 'Token cost', item.currencies.map(cost => cost.count + ' ' + cost.name).join(' + '));
    if (item.photoGeneration) fact(facts,'Photo model',item.photoGeneration);
    content.append(facts);
    if (item.shops.length) {
      content.append(el('h3', 'catalogue-dialog-subtitle', 'Shops in this client'));
      const list = el('ul', 'catalogue-shop-list');
      for (const shop of item.shops) list.append(el('li', '', shop.name + (shop.region ? ' · ' + shop.region : '')));
      content.append(list);
    }
    const stats = Object.entries(item.stats).filter(([, value]) => knownNumber(value));
    if (stats.length) {
      content.append(el('h3', 'catalogue-dialog-subtitle', item.kind === 'horse' ? 'Base stats' : 'Item bonuses'));
      const list = el('dl', 'catalogue-stat-list');
      stats.forEach(([name, value]) => fact(list, name, (value > 0 ? '+' : '') + value));
      content.append(list);
    }
    const notes = [];
    if (item.section === 'Hairstyles' && !item.hairPhotoMatched) notes.push('A matching portrait is not available for this colour, so the original game hairstyle icon is shown.');
    if (item.lockedForPurchase) notes.push('The client marks this item as locked for purchase.');
    if (item.reward) notes.push('This item is marked as a reward.');
    if (notes.length) content.append(el('p', 'catalogue-record-note', notes.join(' ')));
    body.replaceChildren(visual, content);
    const wasOpen = dialog.open;
    if (!wasOpen) dialog.showModal();
    dialog.scrollTop = 0;
    if (wasOpen) visual.querySelector('[aria-pressed="true"]')?.focus({preventScroll:true});
    document.body.classList.add('catalogue-dialog-open');
  }
  byId('catalogue-dialog-close').addEventListener('click', () => dialog.close());
  dialog.addEventListener('close', () => document.body.classList.remove('catalogue-dialog-open'));
  dialog.addEventListener('click', event => {
    if (event.target === dialog) {
      const rect = dialog.getBoundingClientRect();
      if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) dialog.close();
    }
  });
  window.addEventListener('hashchange', () => { if (dialog.open) dialog.close(); });

  function reset() {
    category = '';
    wishlistOnly = false;
    Object.entries(controls).forEach(([key, control]) => {
      control.value = key === 'sort' ? 'featured' : '';
    });
    visible = pageSize;
    categoryButtons();
    sections();
    renderDatabase();
  }
  byId('clear-filters').addEventListener('click', reset);
  byId('empty-clear-filters').addEventListener('click', reset);
  byId('load-more').addEventListener('click', () => { visible += pageSize; renderDatabase(); });
  document.querySelectorAll('[data-catalogue-focus]').forEach(button => button.addEventListener('click', () => {
    reset();
    const focus = button.dataset.catalogueFocus;
    if (focus === 'wishlist') wishlistOnly = true;
    if (focus === 'horses') { category='Horses & Pets'; controls.section.value='Horses'; }
    if (focus === 'hair') { category='Beauty'; controls.section.value='Hairstyles'; }
    if (focus === 'makeup') { category='Beauty'; controls.section.value='Makeup'; }
    categoryButtons();
    sections();
    renderDatabase();
    document.querySelectorAll('[data-catalogue-focus]').forEach(b => b.setAttribute('aria-pressed',String(b===button)));
  }));
  for (const [key, control] of Object.entries(controls)) {
    control.addEventListener(control.matches('input:not([type=checkbox])') ? 'input' : 'change', () => {
      visible = pageSize;
      clearTimeout(renderTimer);
      renderTimer = setTimeout(renderDatabase, key === 'search' ? 120 : 0);
    });
  }
  window.addEventListener('storage', event => {
    if (event.key !== window.BadRosesWishlist.key && event.key !== null) return;
    wishlist.sync(event.newValue);
    if (!loaded) return;
    refreshWishlistFilters();
    renderDatabase();
    refreshWishlistButtons();
  });
  document.addEventListener('keydown', event => {
    if (event.key === '/' && byId('database').classList.contains('active') && !dialog.open &&
        !event.target.closest('input,textarea,select,[contenteditable=true]')) {
      event.preventDefault();
      controls.search.focus();
    }
  });

  async function load() {
    byId('result-count').textContent = 'Opening the catalogue…';
    byId('catalogue-retry').hidden = true;
    try {
      const [dataResponse, metaResponse, variantsResponse] = await Promise.all([fetch('data/database.json?v=hair-assets-4'), fetch('data/catalogue-meta.json?v=hair-assets-4'),fetch('data/catalogue-variants.json?v=hair-assets-4')]);
      if (!dataResponse.ok || !metaResponse.ok || !variantsResponse.ok) throw new Error('Could not load catalogue');
      const [data, meta, variants] = await Promise.all([dataResponse.json(), metaResponse.json(),variantsResponse.json()]);
      variantGroups = variants;
      entries = data.filter(item => item.category !== 'Game Records').map(item => ({ ...item, searchText: [item.title, item.internalName, item.gameId, item.description,
        '#' + item.gameId, item.id, item.category, item.section, item.breed, item.variant, ...item.locations, ...item.events, item.shop,
        ...Object.entries(item.stats).map(([name, value]) => name + ' ' + value), item.reputation?.faction].filter(Boolean).join(' ').toLocaleLowerCase() }));
      loaded = true;
      entryIndex = new Map(entries.map(item=>[item.id,item]));
      variantGroups = Object.fromEntries(Object.entries(variants).map(([key, ids]) => [key, ids.filter(id => entryIndex.has(id))]));
      byId('catalogue-total').textContent = number(entries.length);
      byId('catalogue-horses').textContent = number(meta.horses);
      byId('catalogue-shops').textContent = number(meta.shops);
      categoryButtons();
      sections();
      setOptions(controls.location, [...new Set(entries.flatMap(item => item.locations))].sort(), 'Every location');
      setOptions(controls.hairType, [...new Set(entries.filter(item => item.section === 'Hairstyles').map(item => item.hairType))].sort(), 'Every hairstyle');
      setOptions(controls.hairColour, [...new Set(entries.filter(item => item.section === 'Hairstyles').map(item => item.hairColour))].sort(), 'Every colour');
      const events = [...new Set(entries.flatMap(item => item.events))].sort();
      controls.event.append(...events.map(value => new Option(value, value)));
      const preview = byId('home-items');
      preview.replaceChildren();
      for (const name of ['Horses & Pets', 'Equipment', 'Clothes']) {
        const item = entries.find(entry => entry.category === name && !entry.unlisted && entry.image);
        if (!item) continue;
        const box = el('div', 'preview-item');
        const image = el('img');
        image.src = item.image;
        image.alt = '';
        image.loading = 'lazy';
        image.addEventListener('error', () => { if (item.fallbackImage) image.src = item.fallbackImage; }, { once: true });
        box.append(image, el('span', '', item.title));
        preview.append(box);
      }
      renderDatabase();
    } catch (error) {
      byId('result-count').textContent = 'The catalogue could not be loaded.';
      byId('result-context').textContent = 'Please try again. Local previews need a web server.';
      byId('catalogue-retry').hidden = false;
    }
  }
  byId('catalogue-retry').addEventListener('click', load);
  load();
})();
